import java.io.*;
import java.util.*;

public class Variant3 {
  static PrintWriter output = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

  int N, M;
  long[][] C = new long[61][61];
  int[] Acount = new int[61], Bcount = new int[61];
  long smallestDiff = Long.MAX_VALUE;
  String input;
  Map<Long, Long> dp = new HashMap<>();

  public static void main(String[] args) {
    Variant3 solver = new Variant3();
    solver.solve();
    output.flush();
  }

  static int readInteger() {
    int result = 0;
    boolean isNegative = false;
    try {
      boolean hasStarted = false;
      for (int c = 0; (c = System.in.read()) != -1; ) {
        if (c == '-') {
          hasStarted = true;
          isNegative = true;
          continue;
        } else if (c >= '0' && c <= '9') {
          hasStarted = true;
          result = result * 10 + c - '0';
        } else if (hasStarted) break;
      }
    } catch (IOException ignored) {}
    return isNegative ? -result : result;
  }

  static long readLongNumber() {
    long value = 0;
    boolean isNegative = false;
    try {
      boolean hasStarted = false;
      for (int c = 0; (c = System.in.read()) != -1; ) {
        if (c == '-') {
          hasStarted = true;
          isNegative = true;
          continue;
        } else if (c >= '0' && c <= '9') {
          hasStarted = true;
          value = value * 10 + c - '0';
        } else if (hasStarted) break;
      }
    } catch (IOException ignored) {}
    return isNegative ? -value : value;
  }

  static String readToken() {
    StringBuilder buffer = new StringBuilder();
    try {
      boolean started = false;
      for (int c = 0; (c = System.in.read()) != -1; ) {
        if (Character.isLetterOrDigit(c) || c == '?') {
          started = true;
          buffer.append((char) c);
        } else if (started) break;
      }
    } catch (IOException ignored) {}
    return buffer.toString();
  }

  static int readCharsInto(char[] arr, int start) {
    int length = 0;
    try {
      boolean started = false;
      for (int c = 0; (c = System.in.read()) != -1; ) {
        if (Character.isLetterOrDigit(c)) {
          started = true;
          arr[start + length++] = (char) c;
        } else if (started) break;
      }
    } catch (IOException ignored) {}
    return length;
  }

  void explore(long leftVal, long rightVal, int pos1, int pos2) {
    long diff = Math.abs(leftVal - rightVal);
    if (smallestDiff <= 1 || diff - C[pos1][N] * C[pos2][N] >= smallestDiff) return;
    if (pos1 == N - 1 && pos2 == N - 1) {
      if (diff < smallestDiff) smallestDiff = diff;
      return;
    }
    if (pos1 >= N) {
      long diff1 = C[pos1][N] - C[pos1 - 1][N];
      long factor = C[pos2][N];
      explore(leftVal, rightVal + diff1 * factor, pos1 - 1, pos2);
    }
    if (pos2 >= N) {
      long diff2 = C[pos2][N] - C[pos2 - 1][N];
      long factor = C[pos1][N];
      explore(leftVal + diff2 * factor, rightVal, pos1, pos2 - 1);
    }
  }

  long calculate(long leftVal, long rightVal, int pos1, int pos2) {
    long diff = Math.abs(leftVal - rightVal);
    if (diff - C[pos1][N] * C[pos2][N] > smallestDiff) return 0L;
    long signature = (leftVal << 7) | (pos1 << 4) | pos2;
    Long stored = dp.get(signature);
    if (stored != null) return stored;
    if (pos1 < N || pos2 < N) {
      if (pos1 >= Acount[pos1 + pos2] && pos2 >= Bcount[pos1 + pos2]) {
        int total = pos1 + pos2;
        pos1 -= Acount[total];
        pos2 -= Bcount[total];
        return C[pos1 + pos2][pos1];
      }
      return 0L;
    }
    long total = 0L;
    char ch = input.charAt(pos1 + pos2 - 1);
    if (ch != 'B') {
      long diff1 = C[pos1][N] - C[pos1 - 1][N];
      long factor = C[pos2][N];
      total += calculate(leftVal, rightVal + diff1 * factor, pos1 - 1, pos2);
    }
    if (ch != 'A') {
      long diff2 = C[pos2][N] - C[pos2 - 1][N];
      long factor = C[pos1][N];
      total += calculate(leftVal + diff2 * factor, rightVal, pos1, pos2 - 1);
    }
    dp.put(signature, total);
    return total;
  }

  void solve() {
    N = readInteger();
    M = readInteger();
    for (int i = 0; i <= 2 * (N + M); i++) {
      for (int j = 0; j <= i; j++) {
        if (j == 0 || j == i) C[i][j] = 1;
        else C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
      }
    }
    long left = 0, right = 0;
    int i1 = N + M, i2 = N + M;
    while (i1 >= N && i2 >= N) {
      if (left > right) {
        long diff1 = C[i1][N] - C[i1 - 1][N];
        long factor = C[i2][N];
        right += diff1 * factor;
        i1--;
      } else {
        long diff2 = C[i2][N] - C[i2 - 1][N];
        long factor = C[i1][N];
        left += diff2 * factor;
        i2--;
      }
    }
    smallestDiff = Math.abs(left - right);
    explore(0, 0, N + M, N + M);
    input = readToken();
    for (int i = 0; i < 2 * (N + M); i++) {
      Acount[i + 1] = Acount[i] + (input.charAt(i) == 'A' ? 1 : 0);
      Bcount[i + 1] = Bcount[i] + (input.charAt(i) == 'B' ? 1 : 0);
    }
    long result = calculate(0, 0, N + M, N + M);
    output.println(result);
  }
}
